// ===============================================================
// NEXUS CTF ARCHIVE - Embedded & Encrypted Challenge Assets
// 
// Encrypted using AES-256-CBC.
// Neither the raw PDF bytes nor the plaintext flag string are exposed
// in this file, preventing public GitHub code search leakage.
// ===============================================================

const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

const SEED = 'NEXUS_SYSTEM_ARCHIVE_CIPHER_2026_CORE';
const IV_HEX = '44ec9abea5fb717481abd730cc726048';
const ENC_PDF_HEX = '';
const ENC_FLAG_HEX = '';

function decryptPayload(encHex, ivHex) {
  const key = crypto.createHash('sha256').update(SEED).digest();
  const iv = Buffer.from(ivHex, 'hex');
  const decipher = crypto.createDecipheriv('aes-256-cbc', key, iv);
  return Buffer.concat([decipher.update(Buffer.from(encHex, 'hex')), decipher.final()]);
}

let cachedPdfBuffer = null;
let cachedFlagContent = null;

function getPdfBuffer() {
  if (cachedPdfBuffer) return cachedPdfBuffer;

  // Priority 1: Cloud env var (Base64 encoded PDF)
  if (process.env.CTF_PDF_BASE64) {
    try {
      cachedPdfBuffer = Buffer.from(process.env.CTF_PDF_BASE64, 'base64');
      return cachedPdfBuffer;
    } catch (e) {
      console.error('[EMBEDDED] Failed to parse CTF_PDF_BASE64 env var:', e.message);
    }
  }

  // Priority 2: Local file on disk (if available)
  const candidatePdfPaths = [
    process.env.KNOWLEDGE_PDF_PATH,
    path.join(__dirname, '..', 'Knowledge.pdf'),
    path.join(__dirname, 'Knowledge.pdf')
  ].filter(Boolean);

  for (const candidate of candidatePdfPaths) {
    if (fs.existsSync(candidate)) {
      try {
        cachedPdfBuffer = fs.readFileSync(candidate);
        return cachedPdfBuffer;
      } catch (e) {}
    }
  }

  // Priority 3: Decrypted embedded asset (failsafe standalone)
  cachedPdfBuffer = decryptPayload(ENC_PDF_HEX, IV_HEX);
  return cachedPdfBuffer;
}

function getFlagContent() {
  if (cachedFlagContent) return cachedFlagContent;

  // Priority 1: Cloud env var (Plain flag text or custom message)
  if (process.env.CTF_FLAG) {
    cachedFlagContent = process.env.CTF_FLAG;
    return cachedFlagContent;
  }

  // Priority 2: Local file on disk (if available)
  const candidateFlagPaths = [
    process.env.FLAG_FILE_PATH,
    path.join(__dirname, '..', 'flag.txt'),
    path.join(__dirname, 'flag.txt')
  ].filter(Boolean);

  for (const candidate of candidateFlagPaths) {
    if (fs.existsSync(candidate)) {
      try {
        cachedFlagContent = fs.readFileSync(candidate, 'utf8');
        return cachedFlagContent;
      } catch (e) {}
    }
  }

  // Priority 3: Decrypted embedded asset (failsafe standalone)
  cachedFlagContent = decryptPayload(ENC_FLAG_HEX, IV_HEX).toString('utf8');
  return cachedFlagContent;
}

module.exports = {
  getPdfBuffer,
  getFlagContent
};
